import { repos } from '../core/repositories.js';
import { esc, humanError } from '../core/utils.js';
import { openDetail, openForm, toast, closeModal } from '../ui/components.js';
import { icon } from '../ui/icons.js';
import { openKombaxPublicProfile } from './public-profile.js';
import { contentTranslationAttrs } from '../i18n/user-content-translation.js';

const AVAILABILITY={available:'Disponible',short_notice:'Disponible con poco preaviso',limited:'Disponibilidad limitada',unavailable:'No disponible'};
const CONTACT_MODE={direct:'Contacto directo',club:'A través del club',manager:'A través de manager/representante',direct_or_representative:'Directo o representante'};
const LEVEL={amateur:'Amateur',semi_pro:'Semiprofesional',professional:'Profesional',elite:'Élite'};

function rangeLabel(f){if(f.public_weight_min_kg==null&&f.public_weight_max_kg==null)return 'Peso competitivo no publicado';if(f.public_weight_min_kg!=null&&f.public_weight_max_kg!=null)return `${Number(f.public_weight_min_kg).toFixed(1)}–${Number(f.public_weight_max_kg).toFixed(1)} kg`;return f.public_weight_min_kg!=null?`Desde ${Number(f.public_weight_min_kg).toFixed(1)} kg`:`Hasta ${Number(f.public_weight_max_kg).toFixed(1)} kg`;}

function fighterCard(f,{canInvite=false,standalone=false}={}){return `<article class="kx-fighter-discovery-card"><div class="kx-fighter-discovery-avatar">${f.avatar_url?`<img src="${esc(f.avatar_url)}" alt="">`:`<span>${esc(String(f.nombre_publico||'K').slice(0,2).toUpperCase())}</span>`}</div><div class="kx-fighter-discovery-copy"><header><strong>${esc(f.nombre_publico||'Competidor')}</strong>${f.verificado?'<b>✓ Verificado</b>':''}</header><small>${esc([LEVEL[f.competition_level]||f.competition_level,f.usual_category,rangeLabel(f)].filter(Boolean).join(' · '))}</small><p>${esc([Array.isArray(f.disciplines)?f.disciplines.join(', '):'',f.territory||f.ubicacion,f.club_declarado].filter(Boolean).join(' · '))}</p><div class="kx-fighter-discovery-tags"><span>${esc(AVAILABILITY[f.availability]||f.availability)}</span><span>${esc(CONTACT_MODE[f.contact_mode]||f.contact_mode)}</span>${Number(f.min_notice_hours)<=72?'<span>Short notice</span>':''}</div></div>${canInvite?`<button type="button" class="btn btn-primary btn-sm" data-kx-fighter-invite="${esc(f.competitor_profile_id)}">Invitar al combate</button>`:standalone&&f.social_profile_id?`<button type="button" class="btn btn-ghost btn-sm" data-kx-fighter-profile="${esc(f.social_profile_id)}">Ver perfil / contactar</button>`:''}</article>`;}

function inviteForm(fighter,{event=null,fight=null,onInvited=null}={}){
  const eventAt=event?.fecha_inicio?new Date(event.fecha_inicio).toISOString().slice(0,16):'';
  openForm({title:`Invitar a ${fighter.nombre_publico}`,subtitle:'La invitación no inscribe automáticamente al competidor. Primero debe aceptar y después la organización confirma la inscripción.',width:'760px',fields:[
    {name:'discipline',label:'Disciplina',value:fight?.disciplina||''},{name:'category',label:'Categoría',value:fight?.categoria||fighter.usual_category||''},{name:'proposed_weight_kg',label:'Peso / división propuesta (kg)',type:'number',min:15,max:300,step:'0.1'},{name:'event_at',label:'Fecha y hora',type:'datetime-local',value:eventAt},{name:'location',label:'Lugar',value:event?.lugar_nombre||event?.municipio||''},{name:'message',label:'Mensaje',type:'textarea',rows:4,full:true,maxLength:1200,placeholder:'Contexto del combate, reglas, disponibilidad requerida…'}
  ],submitText:'Enviar invitación',onSubmit:async v=>{await repos.fighterDiscovery.invite({event_id:event?.id,fight_id:fight?.id||null,target_competitor_profile_id:fighter.competitor_profile_id,discipline:v.discipline||'',category:v.category||'',proposed_weight_kg:v.proposed_weight_kg===''?null:Number(v.proposed_weight_kg),event_at:v.event_at?new Date(v.event_at).toISOString():null,location:v.location||'',message:v.message||''});toast('Invitación enviada. El competidor debe aceptarla antes de la inscripción.');await onInvited?.();}});
}

export async function openFighterDiscovery({event=null,fight=null,onInvited=null,standalone=false}={}){
  const seed={discipline:fight?.disciplina||'',category:fight?.categoria||'',weight_kg:null,territory:event?.municipio||'',short_notice:Boolean(event?.fecha_inicio&&((new Date(event.fecha_inicio)-Date.now())/36e5)<=96)};
  const body=`<div class="kx-fighter-discovery"><section class="kx-fighter-discovery-privacy">${icon('shieldCheck',{size:20})}<div><strong>Búsqueda deportiva pública</strong><p>Solo usa disponibilidad, categoría y rango competitivo declarados. Nunca muestra el peso actual ni el histórico privado de preparación.</p></div></section><div class="kx-fighter-discovery-filters"><input id="kx-fd-query" type="search" placeholder="Nombre, club o territorio"><input id="kx-fd-discipline" value="${esc(seed.discipline)}" placeholder="Disciplina"><input id="kx-fd-category" value="${esc(seed.category)}" placeholder="Categoría"><input id="kx-fd-weight" type="number" min="15" max="300" step="0.1" placeholder="Peso kg"><input id="kx-fd-territory" value="${esc(seed.territory)}" placeholder="Territorio"><label><input id="kx-fd-short" type="checkbox" ${seed.short_notice?'checked':''}> Poco preaviso</label><button class="btn btn-primary" id="kx-fd-search">Buscar peleadores</button></div><div id="kx-fd-results"><div class="loading-card">Buscando competidores disponibles…</div></div></div>`;
  const {wrap}=openDetail({title:standalone?'Buscar peleadores':'Buscar sustituto / rival',subtitle:event?.nombre||'KOMBAX Fighter Discovery',body,width:'1040px',className:'kx-fighter-discovery-modal'});
  const run=async()=>{const host=wrap.querySelector('#kx-fd-results');host.innerHTML='<div class="loading-card">Buscando competidores disponibles…</div>';try{const rows=await repos.fighterDiscovery.search({query:wrap.querySelector('#kx-fd-query').value,discipline:wrap.querySelector('#kx-fd-discipline').value||null,category:wrap.querySelector('#kx-fd-category').value||null,weight_kg:wrap.querySelector('#kx-fd-weight').value||null,territory:wrap.querySelector('#kx-fd-territory').value||null,short_notice:wrap.querySelector('#kx-fd-short').checked,limit:50});host.innerHTML=rows.length?`<div class="kx-fighter-discovery-grid">${rows.map(x=>fighterCard(x,{canInvite:Boolean(event?.id),standalone})).join('')}</div>`:'<div class="empty-card compact"><strong>Sin peleadores compatibles</strong><p>Amplía categoría, territorio o rango de búsqueda.</p></div>';host.querySelectorAll('[data-kx-fighter-invite]').forEach(b=>b.addEventListener('click',()=>{const f=rows.find(x=>String(x.competitor_profile_id)===String(b.dataset.kxFighterInvite));if(f)inviteForm(f,{event,fight,onInvited});}));host.querySelectorAll('[data-kx-fighter-profile]').forEach(b=>b.addEventListener('click',()=>{closeModal();openKombaxPublicProfile(b.dataset.kxFighterProfile);}));}catch(error){host.innerHTML=`<div class="empty-card compact"><strong>No se pudo buscar</strong><p>${esc(humanError(error)||error?.message||'Revisa la conexión.')}</p></div>`;}};
  wrap.querySelector('#kx-fd-search')?.addEventListener('click',run);wrap.querySelectorAll('input').forEach(i=>i.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();void run();}}));await run();
}


export async function openFighterOpportunityCenter(competitorProfile,{onDone=null}={}){
  let rows=[];try{rows=await repos.fighterDiscovery.invitations({competitor_profile_id:competitorProfile.id,limit:80});}catch(error){toast(humanError(error)||'No se pudieron cargar las invitaciones.','error');}
  const pending=rows.filter(x=>x.status==='pending');
  const body=`<div class="kx-fighter-opportunity-center"><section class="kx-fighter-discovery-privacy">${icon('shieldCheck',{size:20})}<div><strong>Oportunidades bajo tu control</strong><p>Ser localizable es opcional. Aceptar una invitación no te inscribe automáticamente en el evento ni comparte tu seguimiento privado de peso.</p></div></section><div class="row-actions"><button class="btn btn-primary" id="kx-fighter-availability-edit">Configurar disponibilidad</button></div><section><div class="kx-events-section-head"><div><span>INVITACIONES</span><h3>${pending.length} pendiente${pending.length===1?'':'s'}</h3></div></div>${rows.length?`<div class="kx-fighter-invitation-list">${rows.map(r=>`<article class="kx-fighter-invitation ${esc(r.status)}"><div><span>${esc(String(r.status||'').toUpperCase())}</span><strong ${contentTranslationAttrs({contentId:r.event_id||r.id,contentType:'event',fieldName:'name',sourceLocale:r.source_locale||r.idioma||'',visibility:'public'})}>${esc(r.event_name||'KOMBAX Evento')}</strong><small>${esc([r.discipline,r.category,r.proposed_weight_kg!=null?`${Number(r.proposed_weight_kg).toFixed(1)} kg`:'',r.location].filter(Boolean).join(' · '))}</small>${r.message?`<p ${contentTranslationAttrs({contentId:r.id,contentType:'fighter_invitation',fieldName:'message',sourceLocale:r.source_locale||r.idioma||'',visibility:'private',auto:false})}>${esc(r.message)}</p>`:''}</div>${r.status==='pending'?`<div class="row-actions"><button class="btn btn-primary btn-sm" data-kx-invite-respond="accepted" data-id="${esc(r.id)}">Aceptar</button><button class="btn btn-ghost btn-sm" data-kx-invite-respond="declined" data-id="${esc(r.id)}">Rechazar</button></div>`:`<b>${esc(r.status)}</b>`}</article>`).join('')}</div>`:'<div class="empty-card compact"><strong>Sin invitaciones</strong><p>Cuando un organizador te invite a un combate aparecerá aquí.</p></div>'}</section></div>`;
  const {wrap}=openDetail({title:'Oportunidades de combate',subtitle:competitorProfile.nombre_publico||'Mi Competidor',body,width:'900px'});
  const reopen=async()=>{closeModal();await openFighterOpportunityCenter(competitorProfile,{onDone});};
  wrap.querySelector('#kx-fighter-availability-edit')?.addEventListener('click',()=>openFighterAvailabilityEditor(competitorProfile,{onDone:reopen}));
  wrap.querySelectorAll('[data-kx-invite-respond]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await repos.fighterDiscovery.respond(b.dataset.id,b.dataset.kxInviteRespond);toast(b.dataset.kxInviteRespond==='accepted'?'Invitación aceptada. Falta confirmación de inscripción por la organización.':'Invitación rechazada.');await reopen();}catch(error){b.disabled=false;toast(humanError(error)||'No se pudo responder.','error');}}));
}

// R62.6 compatibility: el seguimiento privado nunca se publica en Discovery; el editor común solo usa estado y datos públicos declarados.
export async function openFighterAvailabilityEditor(competitorProfile,{onDone=null}={}){
  const {openDiscoveryAvailabilityEditor}=await import('./kombax-discovery.js');
  return openDiscoveryAvailabilityEditor({...competitorProfile,tipo:'competidor'},{onDone});
}
